using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class TaskbarLifecycleTests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}

 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern IntPtr WindowFromPoint(D.Point p);
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};try{foreach(var screen in System.Windows.Forms.Screen.AllScreens)foreach(bool transparent in new[]{true,false}){var cfg=new MonitorConfig{Taskbar=true,TaskbarScreen=screen.DeviceName,TaskbarSide="left",TaskbarOffset=400,TaskbarItems=new List<string>{"cpu","memory"}};cfg.Appearance.Transparent=transparent;using(var view=new TaskbarMonitor()){view.Update(new SystemSample{Cpu=40,MemoryUsed=8,MemoryTotal=16,Utc=DateTime.UtcNow},cfg);Pump();Check(view.Visible,"production path shows window "+screen.DeviceName+"/"+transparent);Check(view.LayeredFrames>0,"production path submits first frame "+screen.DeviceName+"/"+transparent);var geometry=(TaskbarGeometry)Get(view,"geometry");using(var surface=TaskbarPainter.Surface(cfg,view.Sample,geometry,view.ClientSize)){D.Point pixel=new D.Point(-1,-1);for(int y=0;y<surface.Height&&pixel.X<0;y++)for(int x=0;x<surface.Width;x++)if(surface.GetPixel(x,y).A==255){pixel=new D.Point(x,y);break;}Check(pixel.X>=0,"rendered frame contains an opaque pixel "+screen.DeviceName+"/"+transparent);if(pixel.X>=0){var point=view.PointToScreen(pixel);Check(WindowFromPoint(point)==view.Handle,"rendered pixel belongs to visible window "+screen.DeviceName+"/"+transparent);using(var capture=new D.Bitmap(1,1))using(var graphics=D.Graphics.FromImage(capture)){graphics.CopyFromScreen(point,D.Point.Empty,new D.Size(1,1));var expected=surface.GetPixel(pixel.X,pixel.Y);var actual=capture.GetPixel(0,0);int difference=Math.Abs(expected.R-actual.R)+Math.Abs(expected.G-actual.G)+Math.Abs(expected.B-actual.B);Check(difference<=18,"actual screen pixel matches rendered frame "+screen.DeviceName+"/"+transparent);}}}long count=view.LayeredFrames;view.Update(new SystemSample{Cpu=65,Utc=DateTime.UtcNow},cfg);Pump();Check(view.LayeredFrames>count,"production path refresh submits new frame "+screen.DeviceName+"/"+transparent);Check(view.LastLayeredError==0,"layered upload has no error "+screen.DeviceName+"/"+transparent);cfg.Taskbar=false;view.Position();Pump();cfg.Taskbar=true;view.Update(new SystemSample{Cpu=50,Utc=DateTime.UtcNow},cfg);Pump();Check(view.Visible&&view.LayeredFrames>count,"hide-show restores content "+screen.DeviceName+"/"+transparent);}}}catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"taskbar-lifecycle-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,production_lifecycle=true}));return failures==0?0:1;}
}
